def compute(vars):
    loss_to_gain_ratio = vars["v1"] / vars["v2"] if vars["v2"] != 0 else None
    if loss_to_gain_ratio is None:
        return None
    return {
        "value": loss_to_gain_ratio,
        "trace": {
            "loss_to_gain_ratio": loss_to_gain_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
